import { Locator, Page, expect } from '@playwright/test';

export class ProductListPage {
  constructor(private readonly page: Page) {}

  async open() {
    await this.page.goto('/#/search');
    await expect(this.page.locator('app-product').first()).toBeVisible();
  }

  product(name: string): Locator {
    return this.page.locator('app-product').filter({
      has: this.page.locator('.name', { hasText: new RegExp(`^${escapeRegExp(name)}$`) }),
    });
  }

  productName(name: string): Locator {
    return this.product(name).locator('.name');
  }

  productPrice(name: string): Locator {
    return this.product(name).locator('.price');
  }

  addToBasketButton(name: string): Locator {
    return this.product(name).getByRole('button', { name: 'Add to Basket' });
  }

  async addToBasket(name: string) {
    await this.addToBasketButton(name).click();
  }
}

function escapeRegExp(text: string) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
import { Locator, Page, expect } from '@playwright/test';

export class PaymentPage {
  readonly title: Locator;
  readonly continueButton: Locator;
  readonly walletSection: Locator;
  readonly couponPanelHeader: Locator;
  readonly couponPanel: Locator;
  readonly couponField: Locator;
  readonly redeemButton: Locator;

  constructor(private readonly page: Page) {
    this.title = page.getByRole('heading', { name: 'My Payment Options' });
    this.continueButton = page.getByRole('button', { name: 'Proceed to review' });
    this.walletSection = page.locator('app-payment .row').filter({ hasText: 'Pay using wallet' });
    this.couponPanelHeader = page.getByRole('button', { name: /^Add a coupon/ });
    this.couponPanel = page.getByRole('region', { name: /Add a coupon/ });
    this.couponField = this.couponPanel.getByRole('textbox', { name: 'Coupon' });
    this.redeemButton = this.couponPanel.getByRole('button', { name: /Redeem/ });
  }

  card(lastDigits: string): Locator {
    return this.page.locator('app-payment-method mat-row').filter({ hasText: `************${lastDigits}` });
  }

  walletBalance(): Locator {
    return this.walletSection.locator('b').filter({ hasText: 'Wallet Balance' });
  }

  payWithWalletButton(amount: string): Locator {
    return this.walletSection.getByRole('button', { name: `Pay ${amount}` });
  }

  async openCouponPanel() {
    await this.couponPanelHeader.click();
    await expect(this.couponField).toBeVisible();
  }

  /** Types the code and clicks `Redeem`; waits for the server answer. */
  async redeemCoupon(code: string) {
    await this.couponField.fill(code);
    const answer = this.page.waitForResponse((r) => /\/rest\/basket\/\d+\/coupon\//.test(r.url()));
    await this.redeemButton.click();
    await answer;
  }

  async selectCard(lastDigits: string) {
    await this.card(lastDigits).getByRole('radio').click();
  }

  async continue() {
    await this.continueButton.click();
    await expect(this.page).toHaveURL(/#\/order-summary$/);
  }
}
