import { test, expect } from './support/fixtures';
import { currentMonthCoupon } from './support/coupon';
import { deliveries, products, savedAddress, savedCard } from './support/test-data';

const product = products.eggfruitJuice;

test.describe('TC-05: Valid coupon on the payment step', () => {
  let coupon: string;

  test.beforeEach(async ({ api, signIn }) => {
    const customer = await api.createCustomer('tc05');
    await api.addSavedAddressAndCard(customer);
    await api.addToBasket(customer, product.name, 2);
    coupon = currentMonthCoupon(await api.serverDate(), 10);
    await signIn(customer);
  });

  test('TC-05', async ({ shop }) => {
    const { basket, address, delivery, payment, summary } = shop;

    await test.step('1. Basket → Checkout', async () => {
      await basket.open();
      await basket.checkout();
      await expect(address.title).toBeVisible();
      await expect(address.address(savedAddress.name)).toContainText(savedAddress.address);
    });

    await test.step('2. Select the saved address → Continue', async () => {
      await address.selectAddress(savedAddress.name);
      await address.continue();
      await expect(delivery.title).toBeVisible();
      await expect(delivery.price(deliveries.oneDay.name)).toHaveText(deliveries.oneDay.price);
      await expect(delivery.price(deliveries.fast.name)).toHaveText(deliveries.fast.price);
      await expect(delivery.price(deliveries.standard.name)).toHaveText(deliveries.standard.price);
    });

    await test.step('3. Select One Day Delivery → Continue', async () => {
      await shop.chooseDelivery(deliveries.oneDay.name);
      await expect(payment.title).toBeVisible();
      await expect(payment.card(savedCard.number.slice(-4))).toContainText(savedCard.name);
      await expect(payment.couponPanelHeader).toBeVisible();
    });

    await test.step('4. Redeem the 10% coupon of the current month', async () => {
      await payment.openCouponPanel();
      await payment.redeemCoupon(coupon);
      await expect(payment.couponPanel).toContainText('Your discount of 10% will be applied during checkout.');
    });

    await test.step('5. Select the saved card → Continue', async () => {
      await payment.selectCard(savedCard.number.slice(-4));
      await payment.continue();
      await summary.expectTotals({
        Items: '17.98¤',
        Delivery: '0.99¤',
        Promotion: '1.80¤',
        'Total Price': '17.17¤',
      });
    });
  });
});
import { test, expect } from './support/fixtures';
import { previousMonthCoupon } from './support/coupon';
import { deliveries, products, savedAddress, savedCard } from './support/test-data';

const product = products.eggfruitJuice;
const invalidCode = 'abcdefghij';

test.describe('TC-06: Invalid coupon and expired coupon', () => {
  let expiredCoupon: string;

  test.beforeEach(async ({ api, signIn }) => {
    const customer = await api.createCustomer('tc06');
    await api.addSavedAddressAndCard(customer);
    await api.addToBasket(customer, product.name, 2);
    expiredCoupon = previousMonthCoupon(await api.serverDate(), 10);
    await signIn(customer);
  });

  test('TC-06', async ({ shop }) => {
    const { delivery, payment, summary } = shop;

    await test.step('1. Basket → Checkout → saved address → Continue', async () => {
      await shop.checkoutToDelivery(savedAddress.name);
      await expect(delivery.title).toBeVisible();
    });

    await test.step('2. Select One Day Delivery → Continue', async () => {
      await shop.chooseDelivery(deliveries.oneDay.name);
      await expect(payment.title).toBeVisible();
    });

    await test.step('3. Redeem an invalid code', async () => {
      await payment.openCouponPanel();
      await payment.redeemCoupon(invalidCode);
      await expect(payment.couponPanel).toContainText('Invalid coupon.');
      await expect(payment.couponPanel).not.toContainText('Your discount of');
    });

    await test.step('4. Redeem the coupon of the previous month', async () => {
      await payment.redeemCoupon(expiredCoupon);
      await expect(payment.couponPanel).toContainText('Invalid coupon.');
      await expect(payment.couponPanel).not.toContainText('Your discount of');
    });

    await test.step('5. Select the saved card → Continue', async () => {
      await payment.selectCard(savedCard.number.slice(-4));
      await payment.continue();
      await summary.expectTotals({
        Items: '17.98¤',
        Delivery: '0.99¤',
        Promotion: '0.00¤',
        'Total Price': '18.97¤',
      });
    });
  });
});
import { Locator, Page, expect } from '@playwright/test';

export class BasketPage {
  readonly basket: Locator;
  readonly rows: Locator;
  readonly totalPrice: Locator;
  readonly checkoutButton: Locator;

  constructor(private readonly page: Page) {
    this.basket = page.locator('app-purchase-basket');
    this.rows = this.basket.locator('mat-row');
    this.totalPrice = page.locator('#price');
    this.checkoutButton = page.locator('#checkoutButton');
  }

  async open() {
    await this.page.goto('/#/basket');
    await expect(this.basket.getByRole('heading', { name: /^Your Basket/ })).toBeVisible();
  }

  row(productName: string): Locator {
    return this.rows.filter({ has: this.page.locator('.mat-column-product', { hasText: productName }) });
  }

  quantity(productName: string): Locator {
    return this.row(productName).locator('.mat-column-quantity > span');
  }

  price(productName: string): Locator {
    return this.row(productName).locator('.mat-column-price');
  }

  async increase(productName: string) {
    await this.row(productName).locator('button:has(.fa-plus-square)').click();
  }

  async decrease(productName: string) {
    await this.row(productName).locator('button:has(.fa-minus-square)').click();
  }

  async remove(productName: string) {
    await this.row(productName).locator('button:has(.fa-trash-alt)').click();
  }

  async checkout() {
    await this.checkoutButton.click();
    await expect(this.page).toHaveURL(/#\/address\/select$/);
  }
}
# TC-05: Valid coupon on the payment step

| Field | Value |
|---|---|
| ID | TC-05 |
| Title | Valid coupon on the payment step |
| Area | Coupon |

The discount of a coupon applies to the price of the products only. The delivery price does not get the discount.

## Preconditions

1. A new customer account exists.
2. The customer is logged in.
3. The customer has one saved address and one saved card. The values are in `README.md`.
4. The basket holds the product with quantity 2. No other products are in the basket.

## Test data

| Name | Value |
|---|---|
| Product | `Eggfruit Juice (500ml)`, price `8.99¤`, quantity 2 |
| Delivery | `One Day Delivery`, price `0.99¤` |
| Coupon | the 10% coupon of the current month, see `README.md` |

Expected order summary:

| Line | Calculation | Value |
|---|---|---|
| `Items` | 2 × 8.99 | `17.98¤` |
| `Delivery` | price of `One Day Delivery` | `0.99¤` |
| `Promotion` | 10% of `Items` | `1.80¤` |
| `Total Price` | `Items` − `Promotion` + `Delivery` | `17.17¤` |

## Steps

| # | Step | Expected result |
|---|---|---|
| 1 | Open the basket `/#/basket`. Click `Checkout`. | The page `Select an address` shows the saved address. |
| 2 | Select the saved address. Click `Continue`. | The page `Choose a delivery speed` shows `One Day Delivery` with price `0.99¤`, `Fast Delivery` with `0.50¤` and `Standard Delivery` with `0.00¤`. |
| 3 | Select `One Day Delivery`. Click `Continue`. | The page `My Payment Options` shows the saved card and the panel `Add a coupon`. |
| 4 | Open the panel `Add a coupon`. Type the coupon code in the field `Coupon`. Click `Redeem`. | The page shows `Your discount of 10% will be applied during checkout.` |
| 5 | Select the saved card. Click `Continue`. | The page `Order Summary` shows `Items` `17.98¤`, `Delivery` `0.99¤`, `Promotion` `1.80¤` and `Total Price` `17.17¤`. |
# TC-06: Invalid coupon and expired coupon

| Field | Value |
|---|---|
| ID | TC-06 |
| Title | Invalid coupon and expired coupon |
| Area | Coupon |

The shop must not give a discount for a code that is not a coupon. The shop must not give a discount for a coupon of a past month.

## Preconditions

1. A new customer account exists.
2. The customer is logged in.
3. The customer has one saved address and one saved card. The values are in `README.md`.
4. The basket holds the product with quantity 2. No other products are in the basket.

## Test data

| Name | Value |
|---|---|
| Product | `Eggfruit Juice (500ml)`, price `8.99¤`, quantity 2 |
| Delivery | `One Day Delivery`, price `0.99¤` |
| Invalid code | `abcdefghij`, 10 characters, not a coupon |
| Expired coupon | the 10% coupon of the previous month, see `README.md` |

Expected order summary, without a discount:

| Line | Value |
|---|---|
| `Items` | `17.98¤` |
| `Delivery` | `0.99¤` |
| `Promotion` | `0.00¤` |
| `Total Price` | `18.97¤` |

## Steps

| # | Step | Expected result |
|---|---|---|
| 1 | Open the basket `/#/basket`. Click `Checkout`. Select the saved address. Click `Continue`. | The page `Choose a delivery speed` opens. |
| 2 | Select `One Day Delivery`. Click `Continue`. | The page `My Payment Options` opens. |
| 3 | Open the panel `Add a coupon`. Type the invalid code in the field `Coupon`. Click `Redeem`. | The page shows the error `Invalid coupon.` The page does not show `Your discount of`. |
| 4 | Type the expired coupon in the field `Coupon`. Click `Redeem`. | The page shows the error `Invalid coupon.` The page does not show `Your discount of`. |
| 5 | Select the saved card. Click `Continue`. | The page `Order Summary` shows `Items` `17.98¤`, `Delivery` `0.99¤`, `Promotion` `0.00¤` and `Total Price` `18.97¤`. |
# Test cases: OWASP Juice Shop v20.3.0

These test cases describe what must work for a customer of the shop.
Each file holds one test case with these parts:

- ID and title
- preconditions
- test data
- steps, with one expected result for each step

## Test environment

- The app is OWASP Juice Shop v20.3.0 at `http://localhost:3000`.
- The app runs in quiet mode (`NODE_ENV=quiet`). Quiet mode turns off the welcome banner, the challenge notifications and the hints.
- The app creates a new database at each start.
- The cookie banner shows on the first visit. The cookie `cookieconsent_status=dismiss` hides it.
- The UI language is English.
- The app shows prices with the sign `¤`.

## Test data rules

- Each test case uses a new customer account. Register the account before the test. Each account has a unique email.
- The account is a normal customer account, not a deluxe account. A deluxe account gets other prices and no purchase limit.
- A test case must not use data from another test case.
- Product names and prices come from the shop catalog of v20.3.0.

## Saved address and saved card

Some test cases need a saved address or a saved card. Create them before the test with these values.

| Field | Value |
|---|---|
| Address: `Country` | `Ukraine` |
| Address: `Name` | `Test Customer` |
| Address: `Mobile Number` | `501234567` |
| Address: `ZIP Code` | `01001` |
| Address: `Address` | `1 Khreshchatyk Street` |
| Address: `City` | `Kyiv` |
| Address: `State` | `Kyiv` |
| Card: `Name` | `Test Customer` |
| Card: `Card Number` | `4111111111111111` |
| Card: `Expiry Month` | `12` |
| Card: `Expiry Year` | `2090` |

## Coupon codes

The shop accepts a coupon only in the month that the coupon names.
A coupon code is the Z85 encoding (ZeroMQ RFC 32) of the text `<MMM><YY>-<NN>`:

