  let coupon: string;

  test.beforeEach(async ({ api, signIn }) => {
    const customer = await api.createCustomer('tc07');
    await api.addSavedAddressAndCard(customer);
    coupon = currentMonthCoupon(await api.serverDate(), 10);
    await signIn(customer);
  });

  test('TC-07', async ({ shop, page }) => {
    const { products: list, basket, header, delivery, payment, summary, completion, orderHistory } = shop;
    let orderId = '';

    await test.step('1. Add product A two times and product B one time', async () => {
      await list.open();
      await list.addToBasket(productA.name);
      await expect(header.basketCounter).toHaveText('1');
      await list.addToBasket(productA.name);
      await expect(header.basketCounter).toHaveText('2');
      await list.addToBasket(productB.name);
      await expect(header.basketCounter).toHaveText('3');
    });

    await test.step('2. Open the basket', async () => {
      await basket.open();
      await expect(basket.rows).toHaveCount(2);
      await expect(basket.quantity(productA.name)).toHaveText('2');
      await expect(basket.quantity(productB.name)).toHaveText('1');
