    await test.step('5. Redeem the 10% coupon', async () => {
      await payment.openCouponPanel();
      await payment.redeemCoupon(coupon);
      await expect(payment.couponPanel).toContainText('Your discount of 10% will be applied during checkout.');
    });

    await test.step('6. Select the saved card → Continue', async () => {
      await payment.selectCard(savedCard.number.slice(-4));
      await payment.continue();
      await expect(summary.deliveryAddress).toContainText(savedAddress.name);
      await expect(summary.deliveryAddress).toContainText(
        `${savedAddress.address}, ${savedAddress.city}, ${savedAddress.state}, ${savedAddress.zipCode}`,
      );
      await expect(summary.deliveryAddress).toContainText(savedAddress.country);
      await expect(summary.paymentMethod).toContainText(`Card ending in ${savedCard.number.slice(-4)}`);
      await summary.expectTotals(expectedTotals);
    });

    await test.step('7. Place your order and pay', async () => {
      await summary.placeOrder();
      await expect(completion.confirmation).toBeVisible();
      orderId = completion.orderId();
      expect(orderId).not.toBe('');
    });

    await test.step('8. Read the order summary on the confirmation page', async () => {
      await expect(completion.productQuantity(productA.name)).toHaveText('2');
      await expect(completion.productQuantity(productB.name)).toHaveText('1');
      await completion.expectTotals(expectedTotals);
    });

    await test.step('9. Basket counter is 0 and the basket is empty', async () => {
      await expect(header.basketCounter).toHaveText('0');
      await basket.open();
      await expect(basket.rows).toHaveCount(0);
      await expect(basket.checkoutButton).toBeDisabled();
    });

    await test.step('10. Order History shows the order', async () => {
      await header.openOrderHistory();
      await expect(page).toHaveURL(/#\/order-history$/);
      await expect(orderHistory.title).toBeVisible();
      await expect(orderHistory.orders).toHaveCount(1);
      const order = orderHistory.order(orderId);
      await expect(orderHistory.orderId(order)).toHaveText(`#${orderId}`);
      await expect(orderHistory.totalPrice(order)).toHaveText('19.86¤');
      await expect(orderHistory.productQuantity(order, productA.name)).toHaveText('2');
      await expect(orderHistory.productQuantity(order, productB.name)).toHaveText('1');
    });
  });
});

