import { Locator, Page, expect } from '@playwright/test';

export type Totals = Record<'Items' | 'Delivery' | 'Promotion' | 'Total Price', string>;

export class OrderSummaryPage {
  readonly heading: Locator;
  readonly deliveryAddress: Locator;
  readonly paymentMethod: Locator;
  readonly placeOrderButton: Locator;
  private readonly summaryRows: Locator;

  constructor(private readonly page: Page) {
    const root = page.locator('app-order-summary');
    this.heading = root.getByText('Order Summary', { exact: true });
    // Cards are nested; the last match is the innermost card with the heading.
    const card = (heading: string) =>
      root.locator('.mdc-card').filter({ has: page.getByText(heading, { exact: true }) }).last();
    this.deliveryAddress = card('Delivery Address');
    this.paymentMethod = card('Payment Method');
    this.placeOrderButton = root.getByRole('button', { name: 'Complete your purchase' });
    this.summaryRows = this.heading.locator('..').getByRole('row');
  }

  basketRow(productName: string): Locator {
    return this.page.locator('app-order-summary app-purchase-basket mat-row').filter({ hasText: productName });
  }

  async totals(): Promise<Partial<Totals>> {
    const result: Record<string, string> = {};
    for (const row of await this.summaryRows.all()) {
      const [label, value] = (await row.getByRole('cell').allInnerTexts()).map((t) => t.trim());
      result[label] = value;
    }
    return result;
  }

  async expectTotals(expected: Totals) {
    await expect(this.heading).toBeVisible();
    await expect.poll(() => this.totals()).toEqual(expected);
  }

  async placeOrder() {
    await this.placeOrderButton.click();
    await expect(this.page).toHaveURL(/#\/order-completion\/[^/]+$/);
  }
}

